details.command:
kubectl patch networkpolicy allow-clients -n server-ns --type merge --patch '
{
  "ingress": [
    {
      "from": [
        {
          "podSelector": {
            "matchLabels": {
              "role": "trusted"
            }
          }
        },
        {
          "namespaceSelector": {
            "matchLabels": {
              "name": "client-ns"
            }
          }
        }
      ],
      "ports": [
        {
          "port": 80,
          "protocol": "TCP"
        }
      ]
    }
  ]
}'

kubectl patch networkpolicy allow-clients -n server-ns --type json --patch='
[
  {
    "op": "replace",
    "path": "/spec/ingress/0/from",
    "value": [
      {
        "podSelector": {
          "matchLabels": {
            "role": "trusted"
          }
        }
      },
      {
        "namespaceSelector": {
          "matchLabels": {
            "name": "client-ns"
          }
        }
      }
    ]
  }
]
'
